#!/usr/bin/env bash
# =============================================================================
# =============================================================================
# InstantGram v1.19.5  -  long-press analytics, chat options, two-tab music,
#                         delete-account by email
#
#   * Analytics, opened the natural way: hold a finger on a post or a clip and
#     choose Insights. Your own clips also get an Insights button. There is no
#     Analytics button in the Me screen any more.
#         Overview    views, accounts reached, engagement, new followers,
#                     views-per-day chart, best posts
#         Reach       accounts reached, reach rate, followers vs newcomers
#         Engagement  likes, comments, shares, reposts, engagement rate
#         Audience    followers, new followers, countries, languages
#         7 / 30 / 90 days, one tap. The numbers come from what the app already
#         writes, and they start counting from this version onwards.
#
#   * Chats: hold a finger on a chat in the inbox to get
#         Pin to the top / Unpin
#         Mute calls / Unmute calls
#         Mute messages / Unmute messages
#         Delete chat
#     Pinned chats float to the top of the inbox. Muting is yours alone - the
#     other person never sees it. firebase/firestore.rules is updated to match
#     (chat flags writable by members, chat and message delete allowed).
#
#   * Music sheet: only two tabs now, "My phone" and "InstantGram audio".
#     The "Hit songs" (Apple) and "Free music" (Openverse) tabs are gone and
#     are not offered for new posts. Older posts that already use one of those
#     tracks keep playing exactly as before.
#
#   * The bell at the top right of Discover opens "Notifications" - the screen
#     used to be titled Activity. Same list, plainer name.
#
#   * Delete account is now a request by email: the screen explains what is
#     removed and opens a ready-written mail to the developer carrying your
#     username, email and user id. No code, no OTP, nothing to configure.
#
# Run from the project root:   bash update_v1195_longpress_analytics.sh
# =============================================================================
set -euo pipefail

EXPECTED_SHA256="e6afcd1c4c8337735e0558ee8591bd31ad7bf3fdfbfdc76284f08179e4cf65e8"

echo "==> Checking project..."
[ -f pubspec.yaml ] || { echo "ERROR: run this from the Flutter project root (pubspec.yaml not found)."; exit 1; }
[ -f lib/services/online_music_service.dart ] || { echo "ERROR: the free music update is not installed. Run update_v1171_free_music.sh first."; exit 1; }
APP_NAME=$(grep -E '^name:' pubspec.yaml | head -1 | awk '{print $2}')

echo "==> Verifying the script (integrity check)..."
TMP_TGZ=$(mktemp /var/tmp/instantgram_payload.XXXXXX.tgz 2>/dev/null || mktemp /tmp/instantgram_payload.XXXXXX.tgz)
# Some browsers save this file with Windows line endings (CRLF). Those
# extra characters corrupt the payload, so strip any control character
# sitting at the end of a line before decoding.
awk '/^__PAYLOAD__/{f=1;next} /^#/{f=0} f' "$0" | sed 's/[[:cntrl:]]*$//' | base64 -d > "$TMP_TGZ" 2>/dev/null || true
ACTUAL=$(sha256sum "$TMP_TGZ" | awk '{print $1}')
if [ "$ACTUAL" != "$EXPECTED_SHA256" ]; then
  echo "ERROR: the script file is incomplete or corrupted (checksum mismatch)."
  echo "       expected  $EXPECTED_SHA256"
  echo "       actual    $ACTUAL"
  echo "       your file is $(wc -c < "$0") bytes; it should be 508342 bytes."
  echo "       Smaller size = the download was cut short: download it again."
  echo "       Same size but still failing, run:"
  echo "         sed -i 's/[[:cntrl:]]*$//' $(basename "$0") && bash $(basename "$0")"
  rm -f "$TMP_TGZ"; exit 1
fi

echo "==> Writing the files (your saved addresses and keys are not touched)..."
tar xzf "$TMP_TGZ" -C .
rm -f "$TMP_TGZ"
chmod +x tools/merge_audio.sh signer/setup.sh 2>/dev/null || true
grep -rl "package:instantgram/" lib test 2>/dev/null | xargs -r sed -i "s#package:instantgram/#package:${APP_NAME}/#" || true

for f in lib/core/config.dart lib/core/agora_key.dart lib/core/giphy_key.dart; do
  [ -f "$f" ] || echo "    WARNING: $f is missing. Run the tools/set_*.sh script that belongs to it."
done

echo ""
echo "Done. v1.19.5 is in place."
echo ""
echo "Good to know:"
echo "  * Hold a post or a clip -> Insights. Your own clips also show a button."
echo "  * Hold a chat in the inbox -> pin, mute calls, mute messages, delete."
echo "  * Deploy firebase/firestore.rules (Firebase console or: firebase deploy"
echo "    --only firestore:rules) or pinning and muting will be refused."
echo "  * The music sheet is down to My phone + InstantGram audio; old tracks"
echo "    from the removed tabs still play."
echo "  * The bell in Discover is now called Notifications."
echo "  * Delete account now sends a ready-written email - nothing to configure."
exit 0

